-- Laundry V1 reference schema — PostgreSQL 16+; UNAPPLIED.
-- Target: EMPTY, separate database in schema public. This is not a Flyway migration
-- and must not be applied to the current F&B database without a reviewed migration plan.
-- UUID values are generated by the application. Money uses NUMERIC(19,2); quantities use NUMERIC(14,3).

CREATE TABLE business_types (
    id UUID PRIMARY KEY,
    code VARCHAR(40) NOT NULL UNIQUE,
    name VARCHAR(80) NOT NULL,
    is_active BOOLEAN NOT NULL DEFAULT TRUE
);
CREATE TABLE plans (
    id UUID PRIMARY KEY,
    code VARCHAR(40) NOT NULL UNIQUE,
    name VARCHAR(80) NOT NULL,
    is_active BOOLEAN NOT NULL DEFAULT TRUE
);
CREATE TABLE plan_versions (
    id UUID PRIMARY KEY,
    plan_id UUID NOT NULL REFERENCES plans(id),
    version_no INTEGER NOT NULL CHECK (version_no > 0),
    status VARCHAR(16) NOT NULL CHECK (status IN ('DRAFT','PUBLISHED','RETIRED')),
    effective_from TIMESTAMPTZ,
    effective_until TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL,
    UNIQUE (plan_id, version_no)
);
CREATE TABLE features (
    id UUID PRIMARY KEY,
    code VARCHAR(80) NOT NULL UNIQUE,
    name VARCHAR(120) NOT NULL,
    description TEXT
);
CREATE TABLE plan_features (
    id UUID PRIMARY KEY,
    plan_version_id UUID NOT NULL REFERENCES plan_versions(id),
    feature_id UUID NOT NULL REFERENCES features(id),
    is_enabled BOOLEAN NOT NULL,
    limit_value INTEGER CHECK (limit_value IS NULL OR limit_value >= 0),
    UNIQUE (plan_version_id, feature_id)
);
CREATE TABLE plan_prices (
    id UUID PRIMARY KEY,
    plan_version_id UUID NOT NULL REFERENCES plan_versions(id),
    currency_code CHAR(3) NOT NULL,
    billing_interval VARCHAR(16) NOT NULL CHECK (billing_interval IN ('MONTHLY','YEARLY')),
    amount NUMERIC(19,2) NOT NULL CHECK (amount >= 0),
    effective_from TIMESTAMPTZ NOT NULL,
    effective_until TIMESTAMPTZ,
    UNIQUE (plan_version_id, id),
    UNIQUE (plan_version_id, currency_code, billing_interval, effective_from)
);
CREATE TABLE staff_users (
    id UUID PRIMARY KEY,
    email VARCHAR(320) NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    full_name VARCHAR(160) NOT NULL,
    status VARCHAR(16) NOT NULL CHECK (status IN ('PENDING_PROFILE','ACTIVE','DISABLED')),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    version BIGINT NOT NULL DEFAULT 0
);
CREATE UNIQUE INDEX ux_staff_users_email_lower ON staff_users (lower(email));

CREATE TABLE tenants (
    id UUID PRIMARY KEY,
    business_type_id UUID NOT NULL REFERENCES business_types(id),
    created_by_user_id UUID NOT NULL REFERENCES staff_users(id),
    onboarding_idempotency_key VARCHAR(128) NOT NULL,
    onboarding_request_fingerprint CHAR(64) NOT NULL,
    legal_name VARCHAR(160),
    display_name VARCHAR(160),
    status VARCHAR(20) NOT NULL CHECK (status IN ('DRAFT','PENDING_SUBSCRIPTION','PENDING_PROFILE','ACTIVE','SUSPENDED','CLOSED')),
    public_slug VARCHAR(100) UNIQUE,
    contact_email VARCHAR(254),
    contact_phone VARCHAR(40),
    logo_url TEXT,
    currency_code CHAR(3) NOT NULL,
    timezone VARCHAR(80) NOT NULL,
    profile_completed_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    version BIGINT NOT NULL DEFAULT 0,
    UNIQUE (created_by_user_id, onboarding_idempotency_key)
);
CREATE TABLE tenant_memberships (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id),
    user_id UUID NOT NULL REFERENCES staff_users(id),
    role_code VARCHAR(20) NOT NULL CHECK (role_code IN ('OWNERMERCHANT','CASHIER')),
    status VARCHAR(16) NOT NULL CHECK (status IN ('INVITED','ACTIVE','DISABLED')),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    version BIGINT NOT NULL DEFAULT 0,
    UNIQUE (tenant_id, id),
    UNIQUE (tenant_id, user_id)
);
CREATE TABLE outlets (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id),
    name VARCHAR(120) NOT NULL,
    phone VARCHAR(40),
    address_line TEXT,
    timezone VARCHAR(80) NOT NULL,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    version BIGINT NOT NULL DEFAULT 0,
    UNIQUE (tenant_id, id),
    UNIQUE (tenant_id, name)
);
CREATE TABLE membership_outlet_access (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id),
    membership_id UUID NOT NULL,
    outlet_id UUID NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    UNIQUE (tenant_id, membership_id, outlet_id),
    FOREIGN KEY (tenant_id, membership_id) REFERENCES tenant_memberships(tenant_id, id),
    FOREIGN KEY (tenant_id, outlet_id) REFERENCES outlets(tenant_id, id)
);

CREATE TABLE subscriptions (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id),
    plan_version_id UUID NOT NULL REFERENCES plan_versions(id),
    plan_price_id UUID NOT NULL,
    status VARCHAR(20) NOT NULL CHECK (status IN ('PENDING_PAYMENT','ACTIVE','PAST_DUE','CANCELLED','EXPIRED')),
    starts_at TIMESTAMPTZ,
    ends_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    version BIGINT NOT NULL DEFAULT 0,
    UNIQUE (tenant_id, id),
    FOREIGN KEY (plan_version_id, plan_price_id) REFERENCES plan_prices(plan_version_id, id)
);
CREATE UNIQUE INDEX ux_subscriptions_one_live_per_tenant ON subscriptions(tenant_id) WHERE status IN ('PENDING_PAYMENT','ACTIVE','PAST_DUE');
CREATE TABLE platform_invoices (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id),
    subscription_id UUID NOT NULL,
    invoice_number VARCHAR(50) NOT NULL UNIQUE,
    currency_code CHAR(3) NOT NULL,
    amount_due NUMERIC(19,2) NOT NULL CHECK (amount_due > 0),
    status VARCHAR(16) NOT NULL CHECK (status IN ('ISSUED','PAID','VOID','EXPIRED')),
    due_at TIMESTAMPTZ,
    issued_at TIMESTAMPTZ NOT NULL,
    paid_at TIMESTAMPTZ,
    UNIQUE (tenant_id, id),
    FOREIGN KEY (tenant_id, subscription_id) REFERENCES subscriptions(tenant_id, id)
);
CREATE TABLE platform_payment_attempts (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id),
    platform_invoice_id UUID NOT NULL,
    provider_code VARCHAR(50) NOT NULL,
    provider_account_ref VARCHAR(120) NOT NULL,
    provider_payment_ref VARCHAR(160),
    amount NUMERIC(19,2) NOT NULL CHECK (amount > 0),
    currency_code CHAR(3) NOT NULL,
    status VARCHAR(20) NOT NULL CHECK (status IN ('CREATED','PENDING','SUCCEEDED','FAILED','EXPIRED')),
    idempotency_key VARCHAR(128) NOT NULL,
    request_fingerprint CHAR(64) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    UNIQUE (tenant_id, idempotency_key),
    UNIQUE (id, provider_code, provider_account_ref),
    UNIQUE (provider_code, provider_account_ref, provider_payment_ref),
    FOREIGN KEY (tenant_id, platform_invoice_id) REFERENCES platform_invoices(tenant_id, id)
);
CREATE TABLE gateway_events (
    id UUID PRIMARY KEY,
    provider_code VARCHAR(50) NOT NULL,
    provider_account_ref VARCHAR(120) NOT NULL,
    provider_event_id VARCHAR(160) NOT NULL,
    provider_payment_ref VARCHAR(160),
    normalized_amount NUMERIC(19,2),
    currency_code CHAR(3),
    normalized_status VARCHAR(20),
    matched_attempt_id UUID,
    event_type VARCHAR(100) NOT NULL,
    payload_digest CHAR(64) NOT NULL,
    received_at TIMESTAMPTZ NOT NULL,
    processed_at TIMESTAMPTZ,
    processing_status VARCHAR(16) NOT NULL CHECK (processing_status IN ('RECEIVED','PROCESSED','REJECTED')),
    UNIQUE (provider_code, provider_account_ref, provider_event_id),
    FOREIGN KEY (matched_attempt_id, provider_code, provider_account_ref) REFERENCES platform_payment_attempts(id, provider_code, provider_account_ref)
);

CREATE TABLE customers (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id),
    full_name VARCHAR(160) NOT NULL,
    phone VARCHAR(40),
    email VARCHAR(254),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    version BIGINT NOT NULL DEFAULT 0,
    UNIQUE (tenant_id, id)
);
CREATE TABLE customer_addresses (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id),
    customer_id UUID NOT NULL,
    label VARCHAR(80),
    recipient_name VARCHAR(160) NOT NULL,
    recipient_phone VARCHAR(40) NOT NULL,
    address_text TEXT NOT NULL,
    latitude NUMERIC(10,7),
    longitude NUMERIC(10,7),
    is_default BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    version BIGINT NOT NULL DEFAULT 0,
    UNIQUE (tenant_id, id),
    FOREIGN KEY (tenant_id, customer_id) REFERENCES customers(tenant_id, id)
);
CREATE UNIQUE INDEX ux_customer_default_address ON customer_addresses(tenant_id, customer_id) WHERE is_default;
CREATE TABLE laundry_service_categories (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id),
    outlet_id UUID NOT NULL,
    name VARCHAR(100) NOT NULL,
    sort_order INTEGER NOT NULL DEFAULT 0,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    version BIGINT NOT NULL DEFAULT 0,
    UNIQUE (tenant_id, id),
    UNIQUE (tenant_id, outlet_id, id),
    UNIQUE (tenant_id, outlet_id, name),
    FOREIGN KEY (tenant_id, outlet_id) REFERENCES outlets(tenant_id, id)
);
CREATE TABLE laundry_services (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id),
    outlet_id UUID NOT NULL,
    category_id UUID,
    name VARCHAR(140) NOT NULL,
    billing_unit VARCHAR(10) NOT NULL CHECK (billing_unit IN ('KG','PIECE')),
    minimum_quantity NUMERIC(14,3) NOT NULL DEFAULT 0 CHECK (minimum_quantity >= 0),
    quantity_increment NUMERIC(14,3) NOT NULL DEFAULT 0.001 CHECK (quantity_increment > 0),
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    version BIGINT NOT NULL DEFAULT 0,
    UNIQUE (tenant_id, id),
    UNIQUE (tenant_id, outlet_id, id),
    UNIQUE (tenant_id, outlet_id, name),
    FOREIGN KEY (tenant_id, outlet_id) REFERENCES outlets(tenant_id, id),
    FOREIGN KEY (tenant_id, outlet_id, category_id) REFERENCES laundry_service_categories(tenant_id, outlet_id, id)
);
CREATE TABLE outlet_laundry_service_prices (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id),
    outlet_id UUID NOT NULL,
    laundry_service_id UUID NOT NULL,
    currency_code CHAR(3) NOT NULL,
    unit_price NUMERIC(19,2) NOT NULL CHECK (unit_price >= 0),
    effective_from TIMESTAMPTZ NOT NULL,
    effective_until TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL,
    UNIQUE (tenant_id, id),
    UNIQUE (tenant_id, outlet_id, id),
    UNIQUE (tenant_id, outlet_id, laundry_service_id, id),
    UNIQUE (tenant_id, outlet_id, laundry_service_id, effective_from),
    FOREIGN KEY (tenant_id, outlet_id) REFERENCES outlets(tenant_id, id),
    FOREIGN KEY (tenant_id, outlet_id, laundry_service_id) REFERENCES laundry_services(tenant_id, outlet_id, id)
);

CREATE TABLE orders (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id),
    outlet_id UUID NOT NULL,
    order_number VARCHAR(50) NOT NULL,
    source VARCHAR(16) NOT NULL CHECK (source IN ('POS','PICKUP_REQUEST')),
    status VARCHAR(16) NOT NULL CHECK (status IN ('RECEIVED','WEIGHED','PROCESSING','READY','HANDED_OVER','COMPLETED','CANCELLED')),
    customer_id UUID,
    customer_name_snapshot VARCHAR(160) NOT NULL,
    customer_phone_snapshot VARCHAR(40),
    subtotal_amount NUMERIC(19,2) NOT NULL CHECK (subtotal_amount >= 0),
    total_amount NUMERIC(19,2) NOT NULL CHECK (total_amount >= 0),
    currency_code CHAR(3) NOT NULL,
    idempotency_key VARCHAR(128) NOT NULL,
    request_fingerprint CHAR(64) NOT NULL,
    received_at TIMESTAMPTZ NOT NULL,
    ready_at TIMESTAMPTZ,
    handed_over_at TIMESTAMPTZ,
    completed_at TIMESTAMPTZ,
    cancelled_at TIMESTAMPTZ,
    cancellation_reason TEXT,
    created_by_membership_id UUID NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    version BIGINT NOT NULL DEFAULT 0,
    UNIQUE (tenant_id, id),
    UNIQUE (tenant_id, outlet_id, id),
    UNIQUE (tenant_id, outlet_id, customer_id, id),
    UNIQUE (tenant_id, outlet_id, order_number),
    UNIQUE (tenant_id, idempotency_key),
    FOREIGN KEY (tenant_id, outlet_id) REFERENCES outlets(tenant_id, id),
    FOREIGN KEY (tenant_id, customer_id) REFERENCES customers(tenant_id, id),
    FOREIGN KEY (tenant_id, created_by_membership_id) REFERENCES tenant_memberships(tenant_id, id),
    CHECK ((status <> 'CANCELLED') OR (cancellation_reason IS NOT NULL AND cancelled_at IS NOT NULL))
);
CREATE TABLE laundry_orders (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id),
    outlet_id UUID NOT NULL,
    estimated_ready_at TIMESTAMPTZ,
    intake_notes TEXT,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    version BIGINT NOT NULL DEFAULT 0,
    UNIQUE (tenant_id, id),
    UNIQUE (tenant_id, outlet_id, id),
    FOREIGN KEY (tenant_id, outlet_id) REFERENCES outlets(tenant_id, id),
    FOREIGN KEY (tenant_id, outlet_id, id) REFERENCES orders(tenant_id, outlet_id, id)
);
CREATE TABLE laundry_order_items (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id),
    outlet_id UUID NOT NULL,
    laundry_order_id UUID NOT NULL,
    laundry_service_id UUID NOT NULL,
    source_price_id UUID NOT NULL,
    service_name_snapshot VARCHAR(140) NOT NULL,
    billing_unit_snapshot VARCHAR(10) NOT NULL CHECK (billing_unit_snapshot IN ('KG','PIECE')),
    billed_quantity NUMERIC(14,3) NOT NULL CHECK (billed_quantity > 0),
    actual_quantity NUMERIC(14,3) CHECK (actual_quantity IS NULL OR actual_quantity > 0),
    minimum_quantity_snapshot NUMERIC(14,3) NOT NULL CHECK (minimum_quantity_snapshot >= 0),
    quantity_increment_snapshot NUMERIC(14,3) NOT NULL CHECK (quantity_increment_snapshot > 0),
    pricing_rule_snapshot VARCHAR(24) NOT NULL CHECK (pricing_rule_snapshot IN ('EXACT_WITH_MINIMUM')),
    estimated_duration_minutes INTEGER CHECK (estimated_duration_minutes IS NULL OR estimated_duration_minutes >= 0),
    estimated_ready_at TIMESTAMPTZ,
    unit_price_snapshot NUMERIC(19,2) NOT NULL CHECK (unit_price_snapshot >= 0),
    line_total_amount NUMERIC(19,2) NOT NULL CHECK (line_total_amount >= 0),
    item_description TEXT,
    condition_notes TEXT,
    created_at TIMESTAMPTZ NOT NULL,
    UNIQUE (tenant_id, id),
    UNIQUE (tenant_id, outlet_id, laundry_order_id, id),
    FOREIGN KEY (tenant_id, outlet_id) REFERENCES outlets(tenant_id, id),
    FOREIGN KEY (tenant_id, outlet_id, laundry_order_id) REFERENCES laundry_orders(tenant_id, outlet_id, id),
    FOREIGN KEY (tenant_id, outlet_id, laundry_service_id) REFERENCES laundry_services(tenant_id, outlet_id, id),
    FOREIGN KEY (tenant_id, outlet_id, laundry_service_id, source_price_id) REFERENCES outlet_laundry_service_prices(tenant_id, outlet_id, laundry_service_id, id),
    CHECK (billing_unit_snapshot <> 'PIECE' OR (billed_quantity = trunc(billed_quantity) AND (actual_quantity IS NULL OR actual_quantity = trunc(actual_quantity))))
);
CREATE TABLE laundry_order_status_history (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id),
    outlet_id UUID NOT NULL,
    order_id UUID NOT NULL,
    from_status VARCHAR(16),
    to_status VARCHAR(16) NOT NULL CHECK (to_status IN ('RECEIVED','WEIGHED','PROCESSING','READY','HANDED_OVER','COMPLETED','CANCELLED')),
    reason TEXT,
    actor_membership_id UUID NOT NULL,
    occurred_at TIMESTAMPTZ NOT NULL,
    FOREIGN KEY (tenant_id, outlet_id) REFERENCES outlets(tenant_id, id),
    FOREIGN KEY (tenant_id, outlet_id, order_id) REFERENCES orders(tenant_id, outlet_id, id),
    FOREIGN KEY (tenant_id, actor_membership_id) REFERENCES tenant_memberships(tenant_id, id)
);
CREATE TABLE pickup_delivery_jobs (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id),
    outlet_id UUID NOT NULL,
    customer_id UUID NOT NULL,
    order_id UUID,
    assigned_membership_id UUID,
    job_type VARCHAR(12) NOT NULL CHECK (job_type IN ('PICKUP','DELIVERY')),
    status VARCHAR(16) NOT NULL CHECK (status IN ('REQUESTED','SCHEDULED','IN_PROGRESS','COMPLETED','CANCELLED')),
    recipient_name_snapshot VARCHAR(160) NOT NULL,
    recipient_phone_snapshot VARCHAR(40) NOT NULL,
    address_snapshot TEXT NOT NULL,
    fee_amount_snapshot NUMERIC(19,2) NOT NULL DEFAULT 0 CHECK (fee_amount_snapshot >= 0),
    currency_code CHAR(3) NOT NULL,
    scheduled_from TIMESTAMPTZ,
    scheduled_until TIMESTAMPTZ,
    completed_at TIMESTAMPTZ,
    notes TEXT,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    version BIGINT NOT NULL DEFAULT 0,
    UNIQUE (tenant_id, id),
    FOREIGN KEY (tenant_id, outlet_id) REFERENCES outlets(tenant_id, id),
    FOREIGN KEY (tenant_id, customer_id) REFERENCES customers(tenant_id, id),
    FOREIGN KEY (tenant_id, outlet_id, customer_id, order_id) REFERENCES orders(tenant_id, outlet_id, customer_id, id),
    FOREIGN KEY (tenant_id, assigned_membership_id) REFERENCES tenant_memberships(tenant_id, id),
    CHECK (job_type = 'PICKUP' OR order_id IS NOT NULL),
    CHECK (status <> 'COMPLETED' OR order_id IS NOT NULL)
);

CREATE TABLE customer_invoices (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id),
    outlet_id UUID NOT NULL,
    order_id UUID NOT NULL,
    invoice_number VARCHAR(50) NOT NULL,
    status VARCHAR(16) NOT NULL CHECK (status IN ('ISSUED','PAID','VOID')),
    currency_code CHAR(3) NOT NULL,
    subtotal_amount NUMERIC(19,2) NOT NULL CHECK (subtotal_amount >= 0),
    discount_amount NUMERIC(19,2) NOT NULL DEFAULT 0 CHECK (discount_amount >= 0 AND discount_amount <= subtotal_amount),
    discount_reason TEXT,
    discount_actor_membership_id UUID,
    fee_amount NUMERIC(19,2) NOT NULL DEFAULT 0 CHECK (fee_amount >= 0),
    tax_amount NUMERIC(19,2) NOT NULL DEFAULT 0 CHECK (tax_amount >= 0),
    total_amount NUMERIC(19,2) NOT NULL CHECK (total_amount > 0 AND total_amount = subtotal_amount - discount_amount + fee_amount + tax_amount),
    issued_at TIMESTAMPTZ NOT NULL,
    paid_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    version BIGINT NOT NULL DEFAULT 0,
    UNIQUE (tenant_id, id),
    UNIQUE (tenant_id, outlet_id, id),
    UNIQUE (tenant_id, outlet_id, order_id, id),
    UNIQUE (tenant_id, order_id),
    UNIQUE (tenant_id, outlet_id, invoice_number),
    FOREIGN KEY (tenant_id, outlet_id) REFERENCES outlets(tenant_id, id),
    FOREIGN KEY (tenant_id, outlet_id, order_id) REFERENCES orders(tenant_id, outlet_id, id),
    FOREIGN KEY (tenant_id, discount_actor_membership_id) REFERENCES tenant_memberships(tenant_id, id),
    CHECK ((discount_amount = 0 AND discount_reason IS NULL AND discount_actor_membership_id IS NULL) OR (discount_amount > 0 AND discount_reason IS NOT NULL AND discount_actor_membership_id IS NOT NULL))
);
CREATE TABLE customer_invoice_lines (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id),
    outlet_id UUID NOT NULL,
    order_id UUID NOT NULL,
    customer_invoice_id UUID NOT NULL,
    laundry_order_item_id UUID NOT NULL,
    description_snapshot VARCHAR(240) NOT NULL,
    quantity_snapshot NUMERIC(14,3) NOT NULL CHECK (quantity_snapshot > 0),
    unit_price_snapshot NUMERIC(19,2) NOT NULL CHECK (unit_price_snapshot >= 0),
    line_total_amount NUMERIC(19,2) NOT NULL CHECK (line_total_amount >= 0),
    created_at TIMESTAMPTZ NOT NULL,
    UNIQUE (tenant_id, id),
    UNIQUE (tenant_id, customer_invoice_id, laundry_order_item_id),
    FOREIGN KEY (tenant_id, outlet_id, order_id, customer_invoice_id) REFERENCES customer_invoices(tenant_id, outlet_id, order_id, id),
    FOREIGN KEY (tenant_id, outlet_id, order_id, laundry_order_item_id) REFERENCES laundry_order_items(tenant_id, outlet_id, laundry_order_id, id)
);
CREATE TABLE customer_payments (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id),
    outlet_id UUID NOT NULL,
    customer_invoice_id UUID NOT NULL,
    amount NUMERIC(19,2) NOT NULL CHECK (amount > 0),
    tendered_amount NUMERIC(19,2) NOT NULL CHECK (tendered_amount >= amount),
    change_amount NUMERIC(19,2) NOT NULL DEFAULT 0 CHECK (change_amount >= 0 AND change_amount = tendered_amount - amount),
    currency_code CHAR(3) NOT NULL,
    method VARCHAR(20) NOT NULL CHECK (method IN ('CASH','MANUAL_NON_CASH')),
    reference_number VARCHAR(120),
    status VARCHAR(16) NOT NULL CHECK (status IN ('POSTED','VOID')),
    idempotency_key VARCHAR(128) NOT NULL,
    request_fingerprint CHAR(64) NOT NULL,
    received_by_membership_id UUID NOT NULL,
    paid_at TIMESTAMPTZ NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    UNIQUE (tenant_id, id),
    UNIQUE (tenant_id, idempotency_key),
    FOREIGN KEY (tenant_id, outlet_id) REFERENCES outlets(tenant_id, id),
    FOREIGN KEY (tenant_id, outlet_id, customer_invoice_id) REFERENCES customer_invoices(tenant_id, outlet_id, id),
    FOREIGN KEY (tenant_id, received_by_membership_id) REFERENCES tenant_memberships(tenant_id, id),
    CHECK (method = 'CASH' OR (change_amount = 0 AND tendered_amount = amount))
);
CREATE UNIQUE INDEX ux_customer_payments_one_posted_invoice ON customer_payments(tenant_id, customer_invoice_id) WHERE status = 'POSTED';

CREATE TABLE inventory_items (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id),
    outlet_id UUID NOT NULL,
    sku VARCHAR(80),
    name VARCHAR(140) NOT NULL,
    unit VARCHAR(30) NOT NULL,
    reorder_level NUMERIC(14,3) NOT NULL DEFAULT 0 CHECK (reorder_level >= 0),
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    version BIGINT NOT NULL DEFAULT 0,
    UNIQUE (tenant_id, id),
    UNIQUE (tenant_id, outlet_id, id),
    UNIQUE (tenant_id, outlet_id, sku),
    FOREIGN KEY (tenant_id, outlet_id) REFERENCES outlets(tenant_id, id)
);
CREATE TABLE inventory_balances (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id),
    outlet_id UUID NOT NULL,
    inventory_item_id UUID NOT NULL,
    quantity_on_hand NUMERIC(14,3) NOT NULL CHECK (quantity_on_hand >= 0),
    updated_at TIMESTAMPTZ NOT NULL,
    version BIGINT NOT NULL DEFAULT 0,
    UNIQUE (tenant_id, outlet_id, inventory_item_id),
    FOREIGN KEY (tenant_id, outlet_id) REFERENCES outlets(tenant_id, id),
    FOREIGN KEY (tenant_id, outlet_id, inventory_item_id) REFERENCES inventory_items(tenant_id, outlet_id, id)
);
CREATE TABLE inventory_movements (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id),
    outlet_id UUID NOT NULL,
    inventory_item_id UUID NOT NULL,
    order_id UUID,
    reversal_of_movement_id UUID,
    movement_type VARCHAR(16) NOT NULL CHECK (movement_type IN ('RECEIPT','USAGE','ADJUSTMENT','REVERSAL')),
    quantity_delta NUMERIC(14,3) NOT NULL CHECK (quantity_delta <> 0),
    reason TEXT NOT NULL,
    idempotency_key VARCHAR(128) NOT NULL,
    request_fingerprint CHAR(64) NOT NULL,
    actor_membership_id UUID NOT NULL,
    occurred_at TIMESTAMPTZ NOT NULL,
    UNIQUE (tenant_id, outlet_id, inventory_item_id, id),
    UNIQUE (tenant_id, idempotency_key),
    UNIQUE (tenant_id, outlet_id, inventory_item_id, reversal_of_movement_id),
    FOREIGN KEY (tenant_id, outlet_id) REFERENCES outlets(tenant_id, id),
    FOREIGN KEY (tenant_id, outlet_id, inventory_item_id) REFERENCES inventory_items(tenant_id, outlet_id, id),
    FOREIGN KEY (tenant_id, outlet_id, order_id) REFERENCES orders(tenant_id, outlet_id, id),
    FOREIGN KEY (tenant_id, outlet_id, inventory_item_id, reversal_of_movement_id) REFERENCES inventory_movements(tenant_id, outlet_id, inventory_item_id, id),
    FOREIGN KEY (tenant_id, actor_membership_id) REFERENCES tenant_memberships(tenant_id, id),
    CHECK (reversal_of_movement_id IS NULL OR reversal_of_movement_id <> id),
    CHECK ((movement_type <> 'REVERSAL' AND reversal_of_movement_id IS NULL) OR (movement_type = 'REVERSAL' AND reversal_of_movement_id IS NOT NULL)),
    CHECK ((movement_type <> 'RECEIPT' OR quantity_delta > 0) AND (movement_type <> 'USAGE' OR quantity_delta < 0))
);
CREATE TABLE audit_logs (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id),
    outlet_id UUID,
    actor_membership_id UUID,
    action VARCHAR(100) NOT NULL,
    entity_type VARCHAR(80) NOT NULL,
    entity_id UUID NOT NULL,
    reason TEXT,
    before_digest CHAR(64),
    after_digest CHAR(64),
    occurred_at TIMESTAMPTZ NOT NULL,
    FOREIGN KEY (tenant_id, outlet_id) REFERENCES outlets(tenant_id, id),
    FOREIGN KEY (tenant_id, actor_membership_id) REFERENCES tenant_memberships(tenant_id, id)
);
CREATE TABLE outbox_messages (
    id UUID PRIMARY KEY,
    tenant_id UUID NOT NULL REFERENCES tenants(id),
    aggregate_type VARCHAR(80) NOT NULL,
    aggregate_id UUID NOT NULL,
    deduplication_key VARCHAR(200) NOT NULL,
    event_type VARCHAR(100) NOT NULL,
    payload JSONB NOT NULL,
    occurred_at TIMESTAMPTZ NOT NULL,
    published_at TIMESTAMPTZ,
    attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    UNIQUE (tenant_id, deduplication_key)
);

CREATE INDEX ix_orders_tenant_outlet_status ON orders(tenant_id, outlet_id, status, received_at DESC);
CREATE INDEX ix_orders_customer ON orders(tenant_id, customer_id, received_at DESC);
CREATE INDEX ix_laundry_items_order ON laundry_order_items(tenant_id, laundry_order_id);
CREATE INDEX ix_laundry_history_order ON laundry_order_status_history(tenant_id, order_id, occurred_at);
CREATE INDEX ix_jobs_tenant_outlet_status ON pickup_delivery_jobs(tenant_id, outlet_id, status, scheduled_from);
CREATE INDEX ix_invoice_issued ON customer_invoices(tenant_id, outlet_id, status, issued_at DESC);
CREATE INDEX ix_inventory_movements_item ON inventory_movements(tenant_id, inventory_item_id, occurred_at DESC);
CREATE INDEX ix_audit_tenant_time ON audit_logs(tenant_id, occurred_at DESC);
CREATE INDEX ix_outbox_unpublished ON outbox_messages(occurred_at) WHERE published_at IS NULL;


CREATE INDEX ix_customer_payments_report ON customer_payments(tenant_id, outlet_id, paid_at) WHERE status = 'POSTED';
